&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;3k277&quot; data-offset-key=&quot;sqqt-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;sqqt-0-0&quot;&gt;&lt;strong&gt;&lt;span data-offset-key=&quot;sqqt-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Operational Agility&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-offset-key=&quot;sqqt-0-1&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;&lt;strong&gt;:&lt;/strong&gt; Successful execution of the &quot;best next action&quot; for marketing requests, reducing the cycle time for logistics and procurement tasks by 15% quarter-over-quarter.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
