&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;61iek&quot; data-offset-key=&quot;71s9j-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;71s9j-0-0&quot;&gt;&lt;span data-offset-key=&quot;71s9j-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Plan roadmaps and milestones with Data Engineering, Analytics, and IT.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;61iek&quot; data-offset-key=&quot;4btg4-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;4btg4-0-0&quot;&gt;&lt;span data-offset-key=&quot;4btg4-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Mentor senior analysts and engineers.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;aqo9p-0-0&quot;&gt;&lt;span data-offset-key=&quot;aqo9p-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;What You Bring:&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;80aam-0-0&quot;&gt;
