&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;1i0pb-0-0&quot;&gt;&lt;span data-offset-key=&quot;1i0pb-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Experience building business cases, including cost, value, and total cost of ownership, and influencing senior leaders to reach agreement.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;61iek&quot; data-offset-key=&quot;1622d-0-0&quot;&gt;
