&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;61iek&quot; data-offset-key=&quot;ap045-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;ap045-0-0&quot;&gt;&lt;span data-offset-key=&quot;ap045-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Funnel economics and performance modeling experience across sales and marketing data.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;61iek&quot; data-offset-key=&quot;1h02s-0-0&quot;&gt;
