&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;fjtq6&quot; data-offset-key=&quot;bqh52-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;bqh52-0-0&quot;&gt;&lt;span data-offset-key=&quot;bqh52-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Deep narrative skills.&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;bqh52-0-1&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; Experience in creating compelling, cohesive stories for complex technical products.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;fjtq6&quot; data-offset-key=&quot;bocjc-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;bocjc-0-0&quot;&gt;&lt;span data-offset-key=&quot;bocjc-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Data-driven mindset.&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;bocjc-0-1&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; Comfortable using analytics, UXR, and support data to inform documentation decisions and prioritize work.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
