&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;fq2gt&quot; data-offset-key=&quot;8f13a-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;8f13a-0-0&quot;&gt;&lt;span data-offset-key=&quot;8f13a-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Track record of using AI to speed up development, debug complex systems, and improve code quality — while owning the outcomes.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
