&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;fq2gt&quot; data-offset-key=&quot;dqghq-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; style=&quot;text-align: justify;&quot; data-offset-key=&quot;dqghq-0-0&quot;&gt;&lt;span data-offset-key=&quot;dqghq-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Eligible to work in Department of Defense (DoD) Impact Level 4 or above cloud service environments.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
