&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;9lrks-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;9lrks-0-0&quot;&gt;&lt;span data-offset-key=&quot;9lrks-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Exposure to the Elastic stack.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
